1	import * as THREE from 'three';
2	import { CONFIG } from '../../config';
3	import { MAT } from '../../core/materials';
4	import { shared, weatherU, windFx } from '../../core/shared';
5	import { windAt } from './impact';
6	import type { WeatherParams } from './state';
7	
8	/* ===== [weather] Gió (mục 4.5): 0 draw call, chỉ uniform + vài hệ số vô hướng =====
9	   - Cây: vá MAT.leaf, MAT.palm VÀ MAT.trunk (D-028) — dịch đỉnh theo hướng gió trong vertex shader, tỉ lệ độ cao điểm trên mặt đất, pha theo vị trí instance.
10	     Thân + cành vá cùng công thức để tán dừa (đặt đúng đỉnh thân, dịch tới 0,06 m mỗi m cao ⇒ ≈ 0,7 m ở ngọn 12 m) không rời thân, cành bóng mát không chọc ra khỏi tán:
11	     điểm cùng độ cao dịch như nhau nên cả cây nghiêng cùng nhau. Bóng đổ không lắc (depth material mặc định) — chấp nhận.
12	   - Dây: option `sway` của bridgePatch (common/shaders.ts) đọc uSwayTp/Ttl/Sh; biên độ tính ở đây: TP và SH tăng theo v², TTL theo đường cong mưa–gió.
13	   - Thuyền, lửa/nước Cầu Rồng, râu rồng, tốc độ sóng: hệ số trong windFx (core/shared.ts), mặc định trung tính.
14	   Gió = 0 (preset `now`): mọi uniform/hệ số về ĐÚNG giá trị trung tính, nhánh shader không chạy. */
15	const smooth = (a: number, b: number, x: number) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
16	
17	function patchTree(mat: THREE.MeshStandardMaterial, key: string) {
18	  mat.customProgramCacheKey = () => key;
19	  mat.onBeforeCompile = (sh) => {
20	    sh.uniforms.uTime = shared.uTime; sh.uniforms.uWindDir = weatherU.uWindDir;
21	    sh.uniforms.uTreeLean = weatherU.uTreeLean; sh.uniforms.uTreeSway = weatherU.uTreeSway;
22	    const w = CONFIG.weather.wind.trees.omega;
23	    sh.vertexShader = sh.vertexShader
24	      .replace('#include <common>', '#include <common>\nuniform float uTime; uniform vec2 uWindDir; uniform float uTreeLean; uniform float uTreeSway;')
25	      .replace('#include <project_vertex>', `#include <project_vertex>
26	        #ifdef USE_INSTANCING
27	        if (uTreeLean + uTreeSway > 0.0) {
28	          vec3 twC = (modelMatrix * vec4(instanceMatrix[3].xyz, 1.0)).xyz;
29	          float twH = max((modelMatrix * instanceMatrix * vec4(transformed, 1.0)).y - ${CONFIG.landY.toFixed(2)}, 0.0);   // độ cao điểm trên mặt đất
30	          float twPh = dot(twC.xz, vec2(0.13, 0.17));
31	          float twG = uTreeLean + uTreeSway * sin(uTime * ${w.toFixed(2)} + twPh);
32	          float twS = uTreeSway * 0.3 * sin(uTime * ${(w * 1.31).toFixed(2)} + twPh * 2.0);
33	          vec3 twD = (vec3(uWindDir.x, 0.0, uWindDir.y) * twG + vec3(-uWindDir.y, 0.0, uWindDir.x) * twS) * twH;
34	          mvPosition.xyz += mat3(viewMatrix) * twD; gl_Position = projectionMatrix * mvPosition;
35	        }
36	        #endif`);
37	  };
38	  mat.needsUpdate = true;
39	}
40	
41	/* Vá shader cây: tán và thân (gọi trong buildWeather, trước khung hình đầu). */
42	export function buildWind() {
43	  patchTree(MAT.leaf, 'tree-leaf-wind');
44	  patchTree(MAT.palm, 'tree-palm-wind');
45	  patchTree(MAT.trunk, 'tree-trunk-wind');   // thân + cành nghiêng cùng tán (xem đầu file)

