48	export function buildPromenade(atlas: Atlas, adMat: THREE.Material, buildings: Building[]): Promenade {
49	  const group = new THREE.Group(); group.name = 'rf-promenade';
50	  const rnd = rng(5150), z0 = -2600, z1 = 2600, n = Math.ceil((z1 - z0) / P.chunk);
51	  const furn: THREE.BufferGeometry[][] = Array.from({ length: 2 * n }, () => []), signs: THREE.BufferGeometry[][] = Array.from({ length: 2 * n }, () => []);
52	  const cid = (sd: number, z: number) => (sd < 0 ? 0 : n) + Math.min(n - 1, Math.max(0, Math.floor((z - z0) / P.chunk)));
53	  // lan can kè + ghế đá + bồn hoa + thùng rác
54	  for (const sd of [-1, 1]) {
55	    for (let z = (sd < 0 ? -2600 : -2300) + 2; z < z1; z += P.railStep) {
56	      if (blocked(z, 4)) continue;
57	      const f = furn[cid(sd, z)], x = sd * (B + 1);
58	      f.push(bx(0.28, 1.1, 0.28, x, Y + 0.5, z, STONE), bx(0.1, 0.07, P.railStep, x, Y + 1.5, z + P.railStep / 2, STEEL), bx(0.06, 0.05, P.railStep, x, Y + 1.05, z + P.railStep / 2, STEEL));
59	    }
60	    for (let z = (sd < 0 ? -2500 : -2200); z < z1; z += P.benchStep) {
61	      const zz = z + (rnd() - 0.5) * 6;
62	      if (blocked(zz, 6)) continue;
63	      const f = furn[cid(sd, zz)], x = sd * (B + 4.5), tow = -sd;      // ghế quay mặt ra sông
64	      f.push(bx(0.5, 0.1, 1.8, x, Y + 0.45, zz, WOOD), bx(0.08, 0.5, 1.8, x - tow * 0.25, Y + 0.55, zz, WOOD), bx(0.45, 0.45, 0.12, x, Y, zz - 0.8, STONE), bx(0.45, 0.45, 0.12, x, Y, zz + 0.8, STONE));
65	      if (rnd() < 0.5) f.push(bx(1.4, 0.55, 1.4, sd * (B + 7), Y, zz + 5, STONE), bx(1.15, 0.25, 1.15, sd * (B + 7), Y + 0.55, zz + 5, [0.25 + rnd() * 0.6, 0.45 + rnd() * 0.3, 0.2 + rnd() * 0.3]));   // bồn hoa
66	      if (rnd() < 0.3) f.push(col(new THREE.CylinderGeometry(0.26, 0.24, 0.85, 8).translate(sd * (B + 3), Y + 0.43, zz - 4), GREEN));   // thùng rác
67	    }
68	  }
69	  // bến du thuyền sông Hàn (bờ Tây, phía Nam Cầu Rồng): phao nổi, cầu dẫn, mái che, thuyền neo
70	  const mz = 104, mx = -(B - 8), mf = furn[cid(-1, mz)];
71	  mf.push(bx(3, 0.5, 46, mx, 0.05, mz, [0.82, 0.82, 0.8]));
72	  for (let k = 0; k < 5; k++) { const z = mz - 18 + k * 9; mf.push(bx(9, 0.4, 1.6, mx + 6, 0.05, z, [0.8, 0.8, 0.78])); mf.push(bx(2.6, 1.0, 7, mx + 11, 0.05, z + 0.5 * (k % 2), [0.95, 0.95, 0.93]), bx(1.4, 0.6, 3, mx + 11, 1.05, z + 0.5 * (k % 2), [0.25, 0.55, 0.7])); }
73	  const ramp = boxAt(9, 0.25, 2.2, 0, 0, 0); ramp.rotateZ(Math.atan2(2.45, 9)); ramp.translate(-B + 4.2, 1.7, mz);
74	  mf.push(col(ramp, [0.75, 0.75, 0.72]));
75	  for (let k = 0; k < 4; k++) { const z = mz - 15 + k * 10; for (const dz of [-1.6, 1.6]) mf.push(bx(0.15, 3, 0.15, mx - 0.5, 0.3, z + dz, STEEL)); mf.push(bx(3.6, 0.15, 4, mx - 0.5, 3.2, z, [0.2, 0.5, 0.65])); }
76	  // cửa hàng tầng trệt ở hàng nhà đầu tiên: mái hiên nhiều màu + bảng hiệu nhỏ lấy từ atlas
77	  const shopSlots = atlas.byKind('shop'); let si = 0;
78	  for (const b of buildings) {
79	    const sd = Math.sign(b.x), ax = Math.abs(b.x);
80	    if (ax < 322 || ax > 362 || Math.abs(b.z) > 1500 || blocked(b.z, 8)) continue;
81	    const face = -sd, xf = b.x + face * (b.w / 2), f = furn[cid(sd, b.z)], w = Math.min(b.d, 14);
82	    f.push(col(boxAt(1.9, 0.25, w, xf + face * 0.95, Y + 3.2, b.z), AWN[Math.floor(rnd() * AWN.length)]));
83	    const s = shopSlots[si++ % shopSlots.length], g = new THREE.PlaneGeometry(4.6, 1.15), [u0, v0, u1, v1] = atlas.rect(s), uv = g.attributes.uv;
84	    for (let i = 0; i < uv.count; i++) uv.setXY(i, lerp(u0, u1, uv.getX(i)), lerp(v0, v1, uv.getY(i)));
85	    g.rotateY(face > 0 ? Math.PI / 2 : -Math.PI / 2); g.translate(xf + face * 0.06, Y + 4.5, b.z);
86	    signs[cid(sd, b.z)].push(g);
87	  }
88	  // dựng từng chunk thành LOD, tọa độ cục bộ quanh tâm chunk
89	  const lodMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.82 });
90	  const chunks: THREE.LOD[] = [];
91	  for (let c = 0; c < 2 * n; c++) {
92	    const sd = c < n ? -1 : 1, zc = z0 + (c % n + 0.5) * P.chunk, cx = sd * (B + 9), detail = new THREE.Group();
93	    const shift = (g: THREE.BufferGeometry) => g.translate(-cx, 0, -zc);
94	    if (furn[c].length) { const mm = new THREE.Mesh(mergeGeometries(furn[c].map((g) => shift(g))), lodMat); mm.castShadow = false; mm.name = `rf-furniture-${c}`; detail.add(mm); }

